import{_ as r,a0 as i,w as l,s as p,ao as u,I as a,x as e,a1 as n,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"“战斗砖块剧场”占据了 Steam 上 Linux游戏排行榜首位 | LCTT x X-CMD","titleTemplate":false,"description":"“战斗砖块剧场”占据了 Steam 上 Linux游戏排行榜首位 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"“战斗砖块剧场”占据了 Steam 上 Linux游戏排行榜首位 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"“战斗砖块剧场”占据了 Steam 上 Linux游戏排行榜首位 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/BattleBlock Theater Now Rules the Steam for Linux Best-Selling List","title":"“战斗砖块剧场”占据了 Steam 上 Linux游戏排行榜首位","tag":"201405","desc":""},"relativePath":"201405/BattleBlock Theater Now Rules the Steam for Linux Best-Selling List.md","filePath":"[post].md"}'),m={name:"201405/BattleBlock Theater Now Rules the Steam for Linux Best-Selling List.md"};function g(L,t,x,f,S,T){const s=i("Link");return l(),p("div",null,[t[11]||(t[11]=u('<h1 id="战斗砖块剧场-占据了-steam-上-linux游戏排行榜首位" tabindex="-1">“战斗砖块剧场”占据了 Steam 上 Linux游戏排行榜首位 <a class="header-anchor" href="#战斗砖块剧场-占据了-steam-上-linux游戏排行榜首位" aria-label="Permalink to ““战斗砖块剧场”占据了 Steam 上 Linux游戏排行榜首位”">​</a></h1><p><img src="http://i1-news.softpedia-static.com/images/news2/BattleBlock-Theater-Now-Rules-the-Steam-for-Linux-Best-Selling-List-442722-2.jpg" alt=""></p><p><strong>Steam for Linux平台在过去几周接受了一些新游戏，其中几个在最畅销名单里有很高的提升。</strong></p><p><strong>小小世界2</strong> 取代原第十位并成为进入这个专属名单里的新游戏。这款游戏基于同名的幻想桌游，这可能是此类型游戏里唯一一个有Linux版本的游戏。</p><p><strong>足球经理2014</strong> 掉到了第九位，但鉴于这是Steam for Linux上最贵的游戏，我们可以有把握地说他依然做的很好。不需要介绍，这款游戏被认为是同类中做得最好的。</p><p><strong>反恐精英：起源</strong> ，游戏结合了原作反恐精英的玩法，使用的是Source引擎，又回到了Steam for Linux最畅销名单顶部，位于第八位。</p><p><strong>伊卡罗斯之炮在线版</strong> ，Muse Games开发的多玩家第一人称射击游戏，游戏有多个平台版本，包括Linux，现在它位于第七位而且它甚至打二五折。</p><p><strong>求生之路2</strong> ， Valve开发的多人合作第一人称射击游戏，仍然是Linux平台最好的游戏之一，位于第六位。</p><p><strong>星界边境 Starbound</strong> ，呵呵鱼工作室开发的一款程序生成冒险类游戏，游戏中玩家玩家扮演了一个逃离了自己星球而只能紧急降落在其他星球的角色，游戏在第五位。这个游戏仍然在开发中，在游戏完成之前就有人买的事实说明了游戏的质量。</p><p><strong>坎巴拉太空计划</strong> ，一个多类型玩法的游戏，游戏中玩家必须要创建自己的太空项目而且要在不杀死宇航员的情况下发射成功，游戏现在在第四位。</p><p><strong>盖瑞模组 Garry&#39;s Mod</strong>, 一个物理沙箱，就其本身而言它甚至不算是个游戏，它存在于第三空间，如果我们想想它的话它确实很奇怪。游戏没有单独的玩家战争，但玩家有完全的自由。</p><p><strong>腐蚀Rust</strong>, 一款第一人称生存游戏，游戏背景发生在一个持久的宇宙中，游戏不再是第一位，但第二位也不是那么糟糕。游戏仍在开发中，没有迹象表明多会儿会发布最终版本。</p><p>Steam for Linux的最畅名单中位于第一位是新领主，叫做 <strong>战斗砖块剧场</strong> 。这是一款由The Behemoth创作并发布的2D战斗平台游戏，游戏特点是有趣的关卡设计和漂亮的图案。</p><p>玩的开心！</p><hr>',15)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),n(s,{href:"http://news.softpedia.com/news/BattleBlock-Theater-Now-Rules-the-Steam-for-Linux-Best-Selling-List-442722.shtml"},{default:o(()=>[...t[0]||(t[0]=[e("http://news.softpedia.com/news/BattleBlock-Theater-Now-Rules-the-Steam-for-Linux-Best-Selling-List-442722.shtml",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("译者：",-1)),n(s,{href:"https://github.com/linuhap"},{default:o(()=>[...t[2]||(t[2]=[e("linuhap",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),n(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),n(s,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const w=r(m,[["render",g]]);export{h as __pageData,w as default};
